function MakeMap($s,$t){$sections=[System.Collections.Generic.List[string]]::new();$lines=$s -split "`r?`n";$in=$false;foreach($l in $lines){$v=$l.Trim();if($v -eq 'Summary'){$in=$true;continue};if($v -eq 'Next steps'){$in=$false};if($in -and $v -match '^[A-Z][A-Za-z0-9 &()’''-]{2,80}$' -and $v -notmatch '^(Invited|Attachments|Meeting records|Summary|Details|Decisions|Aligned)$'){$sections.Add($v)}};$times=[regex]::Matches($t,'\d{2}:\d{2}:\d{2}')|%{$_.Value}|Select-Object -Unique;$body=[System.Collections.Generic.List[string]]::new();$body.Add('# Topic map');$body.Add('');$body.Add('Topic headings are copied from the Gemini summary. Transcript timestamps are listed in source order.');$body.Add('');$body.Add('## Topics');$body.Add('');foreach($x in ($sections|Select-Object -Unique)){$body.Add('- '+$x)};$body.Add('');$body.Add('## Transcript timestamps');$body.Add('');foreach($x in $times){$body.Add('- '+$x)};return $body -join "`n"}
$items=@(@{s='sofia';d='2026-09-04';f='parallel-reasoning'},@{s='sofia';d='2026-09-09';f='smacker-causal-reasoning'},@{s='sofia';d='2026-09-11';f='conditional-reasoning'},@{s='sofia';d='2026-09-15';f='conditional-sufficient-assumptions'},@{s='sofia';d='2026-09-18';f='sufficient-assumptions'},@{s='sofia';d='2026-09-23';f='preptest-and-conditionals'},@{s='charles-moore';d='2026-09-03';f='argument-analysis'},@{s='charles-moore';d='2026-09-14';f='conditional-logic'},@{s='ore';d='2026-09-11';f='argument-structure'},@{s='asia';d='2026-08-25';f='conditional-logic'},@{s='avneet-natt';d='2026-09-08';f='necessary-assumptions'},@{s='yahunatan-zetvy';d='2026-09-02';f='conditional-logic'},@{s='yahunatan-zetvy';d='2026-09-16';f='conditional-logic-and-theology'});foreach($x in $items){$dir="students/$($x.s)/sessions/$($x.d)-$($x.f)";$tf="temp_transcript_$($x.s)_$($x.d).txt";$t=Get-Content $tf -Raw;$sm=Get-Content "$dir/summary.md" -Raw;$before=[regex]::Match($t,'\d{2}:\d{2}:\d{2}');if($before.Success -and $before.Index -gt 0){$t=$t.Substring($before.Index)};$t='# Transcript' + "`n`nSource tab: Gemini Meet transcript.`n`n"+$t;Set-Content "$dir/transcript.md" $t -NoNewline -Encoding utf8;$map=MakeMap $sm $t;Set-Content "$dir/topic-map.md" $map -NoNewline -Encoding utf8};
